function N({registerIndicator:d,nulls:y}){d({id:"oa-imi",name:"Intraday Momentum Index (IMI)",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:1,max:5e3,step:1,tooltip:"Number of bars used in the calculation"}],plots:[{key:"imi",type:"line",title:"IMI",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,b){const I=Math.max(1,Math.floor(Number(b.period)||14)),o=n.length,m=new Array(o).fill(0),p=new Array(o).fill(0),u=new Array(o).fill(NaN);let l=0,s=0;for(let e=0;e<o;e++){const t=n[e].open,i=n[e].close;let a=0,r=0;Number.isFinite(t)&&Number.isFinite(i)&&(i>t?a=i-t:i<t&&(r=t-i)),m[e]=a,p[e]=r,l+=a,s+=r;const c=e-I;c>=0&&(l-=m[c],s-=p[c]);const f=l+s;u[e]=f!==0?100*l/f:50}return{imi:y(u)}}})}export{N as default};
